    if records:
        if not date_last_run:
            bibtask.write_message("INFO: Collection %s has not been previously "
                "analyzed." % collection, stream=sys.stderr, verbose=3)
            modified_records = intbitset(run_sql("SELECT id FROM bibrec"))
