        j = face[1] - 1
        k = face[2] - 1

        ui = face[3] - 1
        uj = face[4] - 1
        uk = face[5] - 1

        ni = face[6] - 1
        nj = face[7] - 1
        nk = face[8] - 1

        if i < 0 or i >= num_vertices:
            i = 0
        if j < 0 or j >= num_vertices:
