            try:
                move_file_to_storage(log_file_path, job_id, 'logs')
                job.latest_log_excerpt = extract_log_excerpt(log_file_path)
            except Exception as e:
                log.error('Failed to move log file for job \'{}\': {}'.format(job_id, str(e)))

        if firehose_report_path:
            try:
                move_file_to_storage(firehose_report_path, job_id, 'reports')
            except Exception as e:
                log.error('Failed to move firehose report for job \'{}\': {}'.format(job_id, str(e)))

        # Emit event indicating that the upload has been accepted and processed
        event_emitter.emit('upload_accepted', job_id, job.result)

        log.info('Job \'{}\' has been marked as done with result: {}'.format(job_id, job.result))

log_file_path = dud.get('X-Log-File')
        firehose_report_path = dud.get('X-Firehose-Report')

        if log_file_path:
            try:
                shutil.move(log_file_path, conf['log_storage_path'])
                job.latest_log_excerpt = log_file_path
            except Exception as e:
                log.error('Failed to move log file to storage: {}'.format(e))

        if firehose_report_path:
            try:
                shutil.move(firehose_report_path, conf['firehose_storage_path'])
            except Exception as e:
                log.error('Failed to move firehose report to storage: {}'.format(e))

        # Emit an event that the upload was accepted
        event_emitter.emit('upload_accepted', job_id, job.result)

        log.info('Upload accepted for job {}: {}'.format(job_id, job.result))

